out <- 'tmp/rank-matched-notes-i18n'
dir.create(out, recursive=TRUE, showWarnings=FALSE)
n <- list(effect_size_nonparametric_u='700', effect_size_nonparametric_n1='50', effect_size_nonparametric_n2='50', effect_size_nonparametric_h='10', effect_size_nonparametric_n='90', effect_size_nonparametric_groups='3')
m <- list(effect_size_mcnemar_b='0', effect_size_mcnemar_c='10', effect_size_mcnemar_p01='0.10', effect_size_mcnemar_p10='0.20')
rank_result <- function(design, extra=list()) effect_size_nonparametric_calculate(modifyList(modifyList(n, list(effect_size_nonparametric_design=design)), extra))
matched_result <- function(design, extra=list()) effect_size_mcnemar_calculate(modifyList(modifyList(m, list(effect_size_mcnemar_design=design)), extra))
designs <- c('rank_biserial_from_u', 'kruskal_epsilon', 'matched_or_counts', 'cohen_g', 'matched_or_probs', 'epsilon_zero', 'counts_no_correction', 'counts_zero_c')
results <- list(rank_result(designs[1]), rank_result(designs[2]), matched_result(designs[3]), matched_result(designs[4]), matched_result(designs[5]), rank_result('kruskal_epsilon', list(effect_size_nonparametric_h='1')), matched_result('matched_or_counts', list(effect_size_mcnemar_b='5')), matched_result('matched_or_counts', list(effect_size_mcnemar_b='10', effect_size_mcnemar_c='0')))
formula_keys <- paste0('sample_size.result.', c('note_rank_orientation', 'note_epsilon_bound', 'note_matched_correction', 'matched_g', 'note_matched_probabilities', 'note_epsilon_bound', 'note_matched_correction', 'note_matched_correction'))
for (i in seq_along(results)) stopifnot(is.null(results[[i]]$error), identical(results[[i]]$method_note, statedu_t(formula_keys[i], 'en')))
tokens <- list('2U / (n1 n2) - 1', '(H - k + 1) / (N - k)', c('b / c', '0.5'), 'p01 / (p01 + p10) - 0.5', 'p01 / p10')
for (lang in c('en','ko','ja','zh','es','fr','de','vi')) for (i in seq_along(tokens)) stopifnot(all(vapply(tokens[[i]], grepl, logical(1), x=statedu_t(formula_keys[i], lang), fixed=TRUE)))
expected <- c(-.44, 8/87, .5/10.5, -.5+1/3, .5, 0, .5, 10.5/.5)
for (i in seq_along(results)) stopifnot(isTRUE(all.equal(results[[i]]$primary_effect_size, expected[i])))
stopifnot(identical(results[[1]]$rank_biserial, results[[1]]$cliffs_delta), results[[3]]$discordant_pairs == 10, results[[8]]$discordant_pairs == 10)
cat('PASS eight actual rank/McNemar cases: signs, zero lower bound, both zero-cell corrections and noncorrected counts; eight-language formula tokens\n')
